pub fn atoi_like_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let mut found_digit = false;
    let mut value: i128 = 0;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        found_digit = true;
        value = value * 10 + i128::from(byte - b'0');
        index += 1;
    }

    if !found_digit {
        return 0;
    }

    let signed = if negative { -value } else { value };
    let clamped_to_long = signed.clamp(i64::MIN as i128, i64::MAX as i128) as i64;
    clamped_to_long as i32
}

#[cfg(test)]
mod tests {
    use super::atoi_like_i32;

    #[test]
    fn parses_expected_examples() {
        assert_eq!(atoi_like_i32("0"), 0);
        assert_eq!(atoi_like_i32("12x"), 12);
        assert_eq!(atoi_like_i32("+7"), 7);
        assert_eq!(atoi_like_i32("abc"), 0);
        assert_eq!(atoi_like_i32("-1"), -1);
    }

    #[test]
    fn matches_common_overflow_shape() {
        assert_eq!(atoi_like_i32("2147483648"), i32::MIN);
        assert_eq!(atoi_like_i32("99999999999999999999999999"), -1);
        assert_eq!(atoi_like_i32("-99999999999999999999999999"), 0);
    }
}

